import test from "node:test";
import assert from "node:assert/strict";
import { PREDICATES, describePredicates, predicateList, predicateSpec } from "../lib/vocab.js";

test("the vocabulary is closed", () => {
	assert.equal(predicateSpec("allergy").pinned, true);
	assert.equal(predicateSpec("relation").kind, "entity");
	assert.equal(predicateSpec("relation").qualifier, "required");
	assert.equal(predicateSpec("favoriteColor"), null);
	assert.ok(predicateList().includes("name"));
	assert.ok(describePredicates().includes("allergy (text/many/pinned)"));
});

test("only the intended predicates are pinned", () => {
	const pinned = Object.entries(PREDICATES).filter(([, spec]) => spec.pinned).map(([name]) => name).sort();
	assert.deepEqual(pinned, [
		"allergy",
		"avoids",
		"communication_style",
		"diet",
		"language",
		"name",
		"nickname",
		"pronoun",
		"timezone",
	]);
});
